using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Forms;
using Hd820GameBridge;

internal static class UiOptimizationHarness {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static readonly List<object> cases=new List<object>();static int failures;
 static object Get(object value,string field){return value.GetType().GetField(field,Flags).GetValue(value);}
 static void Set(object value,string field,object data){value.GetType().GetField(field,Flags).SetValue(value,data);}
 static object Call(object value,string method,params object[] args){return value.GetType().GetMethod(method,Flags).Invoke(value,args);}
 static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static void Run(string name,Action test){try{test();cases.Add(new{Name=name,Passed=true});}catch(Exception error){while(error is TargetInvocationException && error.InnerException!=null)error=error.InnerException;failures++;cases.Add(new{Name=name,Passed=false,Error=error.ToString()});}}
 static string ConfigFolder(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"config-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
 static string[] Settings(int gain){return new[]{"0","50","1",gain.ToString(),"fixture-source","fixture-output"};}
 static AudioEndpoint Endpoint(string id,bool source){return new AudioEndpoint{Id=id,State=1,Name=source?"Voicemeeter Input":"数字输出",Interface=source?"VB-Audio Voicemeeter":"USB PnP Sound Device",Mix=source?new AudioFormat{Rate=48000,Channels=6,Mask=0x3F}:null};}
 static MainForm Form(){var form=new MainForm(true,false,null,null);((NotifyIcon)Get(form,"tray")).Visible=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-10000,-10000);form.Opacity=0;form.Show();foreach(string timer in new[]{"timer","meterTimer","lifecycleTimer"})((System.Windows.Forms.Timer)Get(form,timer)).Stop();return form;}
 static void Close(MainForm form){Call(form,"RequestExit");form.Dispose();}
 static void ClearOwnPreferences(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"bass-settings.txt");if(File.Exists(path))File.Delete(path);}
 [STAThread]static int Main(string[] args){
  string root=AppDomain.CurrentDomain.BaseDirectory;
  if(File.Exists(Path.Combine(root,"bass-settings.txt")) || File.Exists(RoutingSnapshot.PathName))throw new InvalidOperationException("Refuse a fixture with existing user state.");
  Directory.CreateDirectory(Path.Combine(root,"logs"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  Run("output_requires_explicit_confirmation_even_when_unique",delegate{var output=Endpoint("fixture-output",false);Require(RuntimeConfig.Select(new[]{output},false,null)==null,"A generic USB name must not authorize AC3.");Require(RuntimeConfig.Select(new[]{output},false,output.Id)==output,"Saved explicit output remains usable.");var input=Endpoint("fixture-source",true);Require(RuntimeConfig.Select(new[]{input},true,null)==input,"Unique validated virtual input is still discoverable.");});
  Run("slider_and_combo_receive_arrow_keys",delegate{
   using(var slider=new ModernSlider()){slider.Maximum=100;slider.Value=40;Require((bool)Call(slider,"IsInputKey",Keys.Right),"Right arrow must reach the custom control.");Call(slider,"OnKeyDown",new KeyEventArgs(Keys.Right));Require(slider.Value==41,"Arrow key must adjust gain.");Call(slider,"OnKeyDown",new KeyEventArgs(Keys.End));Require(slider.Value==100,"End must select maximum.");}
   using(var combo=new ModernCombo()){combo.Items.AddRange(new object[]{"first","second"});combo.SelectedIndex=0;Require((bool)Call(combo,"IsInputKey",Keys.Down),"Down arrow must reach the custom control.");Call(combo,"OnKeyDown",new KeyEventArgs(Keys.Down));Require(combo.SelectedIndex==1,"Arrow key must select the next device.");}
  });
  Run("preferences_keep_last_good_backup",delegate{string path=ConfigFolder();RuntimeConfig.SavePreferences(path,Settings(40));RuntimeConfig.SavePreferences(path,Settings(65));Require(RuntimeConfig.Preferences(path)[3]=="65","Latest valid settings are used.");Require(File.ReadAllLines(RuntimeConfig.PreferencesBackupPath(path))[3]=="40","Previous valid settings are retained.");});
  Run("corrupt_preferences_recover_and_preserve_original",delegate{string path=ConfigFolder();RuntimeConfig.SavePreferences(path,Settings(40));RuntimeConfig.SavePreferences(path,Settings(65));string main=Path.Combine(path,"bass-settings.txt");File.WriteAllText(main,"broken settings");string warning;Require(RuntimeConfig.Preferences(path,out warning)[3]=="40" && warning!=null,"Corrupt primary must recover a valid backup with a visible warning.");Require(File.ReadAllText(main)=="broken settings","Recovery must not overwrite corrupt evidence.");RuntimeConfig.SavePreferences(path,Settings(70));Require(Directory.GetFiles(Path.Combine(path,"logs"),"badprefs-*.txt").Length==1,"Explicit new settings must archive the corrupt original.");Require(File.ReadAllLines(RuntimeConfig.PreferencesBackupPath(path))[3]=="40","Corruption must not replace the good backup.");File.WriteAllText(main,"broken again");RuntimeConfig.SavePreferences(path,Settings(75));Require(Directory.GetFiles(Path.Combine(path,"logs"),"badprefs-*.txt").Length==2,"Repeated recovery must keep two distinct originals without overwriting.");});
  Run("unrecoverable_preferences_do_not_fall_back_to_guessed_devices",delegate{string path=ConfigFolder();File.WriteAllText(Path.Combine(path,"bass-settings.txt"),"bad");bool rejected=false;try{RuntimeConfig.Preferences(path);}catch(IOException){rejected=true;}Require(rejected,"Unreadable saved selection must not silently become an empty selection.");});
  Run("oversized_preferences_are_rejected_then_archived",delegate{string path=ConfigFolder();string main=Path.Combine(path,"bass-settings.txt");using(var file=File.Create(main)){file.SetLength(1024*1024);}bool rejected=false;try{RuntimeConfig.Preferences(path);}catch(IOException){rejected=true;}Require(rejected,"Oversized preferences must be rejected before parsing.");RuntimeConfig.SavePreferences(path,Settings(25));string[] archives=Directory.GetFiles(Path.Combine(path,"logs"),"badprefs-*.txt");Require(archives.Length==1 && new FileInfo(archives[0]).Length==1024*1024,"Explicit replacement must preserve the rejected original without decoding it.");});
  Run("atomic_write_uses_short_sibling_for_long_destination",delegate{string directory=ConfigFolder();int length=250-directory.Length-1;Require(length>20,"Fixture depth must retain a valid destination filename.");string path=Path.Combine(directory,new string('x',length));Require(path.Length==250,"The target must exercise legacy path headroom.");RuntimeConfig.AtomicWrite(path,"first");RuntimeConfig.AtomicWrite(path,"second");Require(File.ReadAllText(path)=="second","A valid long destination must support both create and replace.");Require(Directory.GetFiles(directory,".t*.tmp").Length==0,"Atomic writes must clean their short temporary siblings.");string deep=Path.Combine(directory,new string('d',240-directory.Length-1));Directory.CreateDirectory(deep);path=Path.Combine(deep,"state.txt");Require(path.Length==250 && deep.Length==240,"Exercise a long directory as well as a long filename.");RuntimeConfig.AtomicWrite(path,"third");RuntimeConfig.AtomicWrite(path,"fourth");Require(File.ReadAllText(path)=="fourth" && Directory.GetFiles(deep,".t*.tmp").Length==0,"Temporary names must shrink to the remaining legacy path budget.");});
  Run("readonly_preferences_failure_preserves_file",delegate{string path=ConfigFolder();RuntimeConfig.SavePreferences(path,Settings(40));string main=Path.Combine(path,"bass-settings.txt");File.SetAttributes(main,File.GetAttributes(main)|FileAttributes.ReadOnly);bool rejected=false;try{RuntimeConfig.SavePreferences(path,Settings(70));}catch(IOException){rejected=true;}catch(UnauthorizedAccessException){rejected=true;}finally{File.SetAttributes(main,FileAttributes.Normal);}Require(rejected && File.ReadAllLines(main)[3]=="40","A failed replace must retain the original settings.");});
  Run("repeated_slider_changes_are_debounced_and_flushed",delegate{
   using(var form=Form()){var slider=(ModernSlider)Get(form,"gain");for(int i=0;i<300;i++){slider.Value=i%100;Call(form,"SavePreferences");}Require(!File.Exists(Path.Combine(root,"bass-settings.txt")),"Dragging must not synchronously rewrite settings.");Require((bool)Get(form,"preferencesDirty"),"Latest settings must remain pending.");Call(form,"FlushPreferences");Require(File.ReadAllLines(Path.Combine(root,"bass-settings.txt"))[3]==slider.Value.ToString(),"Flush must write the final value.");DateTime saved=File.GetLastWriteTimeUtc(Path.Combine(root,"bass-settings.txt"));Thread.Sleep(20);Call(form,"SavePreferences");Call(form,"FlushPreferences");Require(File.GetLastWriteTimeUtc(Path.Combine(root,"bass-settings.txt"))==saved,"Unchanged settings must not rewrite the file.");Close(form);}
   ClearOwnPreferences();
  });
  Run("idle_timer_and_unchanged_meter_do_not_repaint",delegate{
   using(var form=Form()){Require(!((System.Windows.Forms.Timer)Get(form,"timer")).Enabled,"Idle engine status timer must stay stopped.");Close(form);}
   using(var meter=new ChannelMeterControl()){meter.Size=new Size(820,220);meter.CreateControl();int invalidations=0;meter.Invalidated+=delegate{invalidations++;};for(int i=0;i<100;i++)meter.SetSnapshot(null);Require(invalidations==0,"An unchanged waiting meter must not repaint at 20fps.");long now=DateTime.UtcNow.Ticks;var snapshot=new ChannelMeterSnapshot(new[]{-72d,-72,-72,-72,-72,-72},new[]{-72d,-72,-72,-72,-72,-72},now,2400);meter.SetSnapshot(snapshot,now);int first=invalidations;for(int i=0;i<100;i++)meter.SetSnapshot(snapshot,now+i);Require(invalidations==first,"Repeated fresh silence must not repaint.");}
  });
  Run("telemetry_interval_defaults_and_bounds",delegate{
   string fg=Environment.GetEnvironmentVariable("HD820_TELEMETRY_FOREGROUND_MS"),bg=Environment.GetEnvironmentVariable("HD820_TELEMETRY_BACKGROUND_MS");try{Environment.SetEnvironmentVariable("HD820_TELEMETRY_FOREGROUND_MS",null);Environment.SetEnvironmentVariable("HD820_TELEMETRY_BACKGROUND_MS",null);Require(RuntimeConfig.TelemetryIntervalMilliseconds(true)==2000 && RuntimeConfig.TelemetryIntervalMilliseconds(false)==5000,"Foreground/background cadence must preserve useful telemetry.");Environment.SetEnvironmentVariable("HD820_TELEMETRY_BACKGROUND_MS","1");Require(RuntimeConfig.TelemetryIntervalMilliseconds(false)==1000,"Reject excessive write frequency.");Environment.SetEnvironmentVariable("HD820_TELEMETRY_BACKGROUND_MS","999999");Require(RuntimeConfig.TelemetryIntervalMilliseconds(false)==60000,"Bound configured telemetry intervals.");}finally{Environment.SetEnvironmentVariable("HD820_TELEMETRY_FOREGROUND_MS",fg);Environment.SetEnvironmentVariable("HD820_TELEMETRY_BACKGROUND_MS",bg);}
  });
  Run("diagnostics_complete_hidden_without_reopening_and_drop_late_callback",delegate{
   using(var form=Form()){Call(form,"StartDiagnostics");Require((bool)Get(form,"diagnosticBusy"),"A check must be in flight.");Call(form,"StartDiagnostics");var watch=Stopwatch.StartNew();while((bool)Get(form,"diagnosticBusy") && watch.ElapsedMilliseconds<16000){Application.DoEvents();Thread.Sleep(10);}Require(!(bool)Get(form,"diagnosticBusy") && Get(form,"pendingDiagnosticReport")!=null && !form.Visible,"A hidden form must retain a report without reopening.");Close(form);Call(form,"CompleteDiagnostics","late report");Require((string)Get(form,"pendingDiagnosticReport")!="late report","Disposed windows must ignore late results.");}
  });
  Run("missing_ffmpeg_stops_permanent_autostart_retry",delegate{
   Require(!File.Exists(Path.Combine(root,"ffmpeg.exe"))&&!File.Exists(Path.Combine(root,"ffmpeg-path.txt")),"No FFmpeg fixture may launch here.");
   string savedPath=Environment.GetEnvironmentVariable("PATH");try{Environment.SetEnvironmentVariable("PATH","");using(var form=Form()){var source=(ModernCombo)Get(form,"source");var output=(ModernCombo)Get(form,"output");source.Items.Clear();output.Items.Clear();source.Items.Add(Endpoint("fixture-input",true));output.Items.Add(Endpoint("fixture-output",false));source.SelectedIndex=output.SelectedIndex=0;Set(form,"autoStartPending",true);Call(form,"StartBridge",false);Require(!(bool)Get(form,"autoStartPending") && Get(form,"engine")==null && Get(form,"startupWorker")==null,"A permanent dependency error must not keep retrying or start audio.");Require(((Label)Get(form,"status")).Text.Contains("无声检查"),"Dependency failure needs an actionable explanation.");Close(form);}}finally{Environment.SetEnvironmentVariable("PATH",savedPath);ClearOwnPreferences();}
  });
  var result=new{Passed=failures==0,CaseCount=cases.Count,FailureCount=failures,Cases=cases,FixtureBaseDirectory=root,FixtureBasePathLength=root.Length,Scope="Isolated files and UI controls only. No production Main, global IPC, task/route setters, audio Start, playback, capture, or input injection. Startup/endpoint getters and bounded silent preflight may read host state."};
  string json=new JavaScriptSerializer{MaxJsonLength=1000000}.Serialize(result);File.WriteAllText(args.Length>0?args[0]:Path.Combine(root,"ui-optimization-evidence.json"),json);Console.WriteLine(json);return failures==0?0:1;
 }
}
